const input = $input.first().json || {};

function parseIfJsonString(value) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function asObject(value) {
  const parsed = parseIfJsonString(value);
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  return null;
}

function decodeHtml(value) {
  if (typeof value !== 'string') return value;

  const named = {
    amp: '&',
    lt: '<',
    gt: '>',
    quot: '"',
    nbsp: ' ',
    apos: "'",
    ccedil: 'ç',
    Ccedil: 'Ç',
    atilde: 'ã',
    Atilde: 'Ã',
    aacute: 'á',
    Aacute: 'Á',
    eacute: 'é',
    Eacute: 'É',
    iacute: 'í',
    Iacute: 'Í',
    oacute: 'ó',
    Oacute: 'Ó',
    uacute: 'ú',
    Uacute: 'Ú',
    agrave: 'à',
    Agrave: 'À',
    ecirc: 'ê',
    Ecirc: 'Ê',
    ocirc: 'ô',
    Ocirc: 'Ô',
    acirc: 'â',
    Acirc: 'Â',
    uuml: 'ü',
    Uuml: 'Ü'
  };

  return value
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(parseInt(dec, 10)))
    .replace(/&([a-zA-Z]+);/g, (full, name) => (name in named ? named[name] : full));
}

function maybeFixMojibake(value) {
  if (typeof value !== 'string') return value;

  const direct = value
    .replace(/NÃO/g, 'NÃO')
    .replace(/NÃ£O/g, 'NÃO')
    .replace(/NÃ£o/g, 'Não')
    .replace(/NÃO/g, 'NÃO')
    .replace(/Ã§/g, 'ç')
    .replace(/Ã£/g, 'ã')
    .replace(/Ã¡/g, 'á')
    .replace(/Ã©/g, 'é')
    .replace(/Ã­/g, 'í')
    .replace(/Ã³/g, 'ó')
    .replace(/Ãº/g, 'ú');

  try {
    const repaired = decodeURIComponent(escape(direct));
    const directNoise = (direct.match(/[Ã�]/g) || []).length;
    const repairedNoise = (repaired.match(/[Ã�]/g) || []).length;
    return repairedNoise < directNoise ? repaired : direct;
  } catch {
    return direct;
  }
}

function normalizeString(value) {
  if (value === null || value === undefined) return null;
  const str = maybeFixMojibake(decodeHtml(String(value)));
  const out = str.trim();
  return out === '' ? null : out;
}

function toAsciiFold(value) {
  return String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase();
}

function normalizeYesNo(value) {
  const str = normalizeString(value);
  if (!str) return null;

  const folded = toAsciiFold(str).replace(/[^A-Z]/g, '');
  if (folded === 'SIM') return 'SIM';
  if (folded === 'NAO') return 'NÃO';
  return str;
}

function normalizeSituacao(value) {
  const str = normalizeString(value);
  if (!str) return null;

  const folded = toAsciiFold(str);
  if (folded === 'ATENDIDO') return 'Atendido';
  if (folded === 'CANCELADO') return 'Cancelado';
  if (folded === 'EM ABERTO') return 'Em Aberto';
  return str;
}

function normalizeLocalPrestacao(value) {
  const str = normalizeString(value);
  if (!str) return null;

  const folded = toAsciiFold(str);
  if (folded.includes('ENDERECO DO EMITENTE')) return 'Endereço do Emitente';
  return str;
}

function parseDecimal(value, scale = 2) {
  if (value === null || value === undefined || value === '') return null;
  const raw = String(value).trim();
  let normalized = raw;

  if (raw.includes(',') && raw.includes('.')) {
    normalized = raw.replace(/\./g, '').replace(',', '.');
  } else if (raw.includes(',')) {
    normalized = raw.replace(',', '.');
  }

  normalized = normalized.replace(/[^0-9.-]/g, '');
  const n = Number(normalized);
  if (!Number.isFinite(n)) return null;
  return Number(n.toFixed(scale));
}

function parseInteger(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(String(value).replace(/[^0-9-]/g, ''));
  return Number.isInteger(n) ? n : null;
}

function parseTimestamp(value) {
  if (value === null || value === undefined || value === '') return null;
  const raw = String(value).trim();

  if (/^\d{13}$/.test(raw)) {
    const ms = Number(raw);
    return Number.isFinite(ms) ? Math.floor(ms / 1000) : null;
  }

  if (/^\d{10}$/.test(raw)) {
    const sec = Number(raw);
    return Number.isFinite(sec) ? sec : null;
  }

  const dt = new Date(raw);
  if (Number.isNaN(dt.getTime())) return null;
  return Math.floor(dt.getTime() / 1000);
}

const candidates = [
  asObject(input.body),
  asObject(input),
  asObject(input.original_request?.body),
  asObject(input.original_request),
  asObject(input.query),
  asObject(input.parameters)
].filter(Boolean);

let payload = null;
for (const candidate of candidates) {
  if (Array.isArray(candidate.data?.source?.itens)) {
    payload = candidate;
    break;
  }
}

if (!payload) {
  return {
    _valid: false,
    statusCode: 400,
    body: { ok: false, error: 'Missing required structure: data.source.itens' }
  };
}

const itens = payload.data.source.itens || [];
if (!Array.isArray(itens) || itens.length === 0) {
  return {
    _valid: false,
    statusCode: 400,
    body: { ok: false, error: 'itens must be a non-empty array' }
  };
}

const idsSeen = new Set();
const records = [];
const errors = [];

for (let i = 0; i < itens.length; i++) {
  const item = itens[i] || {};
  const idRegistro = normalizeString(item.ID);
  if (!idRegistro) {
    errors.push({ index: i, error: 'Missing ID' });
    continue;
  }

  if (idsSeen.has(idRegistro)) continue;
  idsSeen.add(idRegistro);

  records.push({
    id_registro: idRegistro,
    rps: normalizeString(item.RPS),
    nota: normalizeString(item.Nota),
    cliente: normalizeString(item.Cliente),
    cnpj: normalizeString(item.CNPJ),
    endereco: normalizeString(item.Endereco),
    numero: normalizeString(item.Numero),
    complemento: normalizeString(item.Complemento),
    bairro: normalizeString(item.Bairro),
    cidade: normalizeString(item.Cidade),
    estado: normalizeString(item.Estado),
    cep: normalizeString(item.CEP),
    email: normalizeString(item.Email),
    telefone: normalizeString(item.Telefone),
    vendedor: normalizeString(item.Vendedor),
    valor_servicos: parseDecimal(item.ValorServicos, 2),
    valor_total: parseDecimal(item.ValorTotal, 2),
    total_parcelas: parseInteger(item.TotalParcelas),
    valor_deducoes: parseDecimal(item.ValorDeducoes, 2),
    aliquota: parseDecimal(item.Aliquota, 2),
    valor_iss: parseDecimal(item.ValorISS, 2),
    iss_retido: normalizeYesNo(item.ISSRetido),
    valor_cofins: parseDecimal(item.ValorCOFINS, 2),
    valor_pis: parseDecimal(item.ValorPIS, 2),
    valor_csll: parseDecimal(item.ValorCSLL, 2),
    valor_ir: parseDecimal(item.ValorIR, 2),
    valor_inss: parseDecimal(item.ValorINSS, 2),
    valor_tributos: parseDecimal(item.ValorTributos, 2),
    data_pedido: parseTimestamp(item.DataPedido),
    local_prestacao: normalizeLocalPrestacao(item.LocalPrestacao),
    contas: normalizeYesNo(item.Contas),
    chave: normalizeString(item.Chave),
    protocolo: normalizeString(item.Protocolo),
    descricao: normalizeString(item.Descricao),
    data_emissao: parseTimestamp(item.DataEmissao),
    situacao: normalizeSituacao(item.Situacao),
    data_cad: parseTimestamp(item.DataCad),
    data_mod: parseTimestamp(item.DataMod)
  });
}

if (errors.length > 0) {
  return {
    _valid: false,
    statusCode: 400,
    body: {
      ok: false,
      error: 'Global failure: one or more items are invalid',
      details: errors
    }
  };
}

if (records.length === 0) {
  return {
    _valid: false,
    statusCode: 400,
    body: { ok: false, error: 'No valid records to process' }
  };
}

return {
  _valid: true,
  itens_received: itens.length,
  itens_processed: records.length,
  records
};

const ctx = $items('Validar e Organizar Dados', 0, 0)[0].json;
const rows = Array.isArray(ctx.records) ? ctx.records : [];

const textFields = [
  'id_registro', 'rps', 'nota', 'cliente', 'cnpj', 'endereco', 'numero',
  'complemento', 'bairro', 'cidade', 'estado', 'cep', 'email', 'telefone',
  'vendedor', 'iss_retido', 'local_prestacao', 'contas', 'chave', 'protocolo',
  'descricao', 'situacao'
];

const numberFields = [
  'valor_servicos', 'valor_total', 'valor_deducoes', 'aliquota',
  'valor_iss', 'valor_cofins', 'valor_pis', 'valor_csll',
  'valor_ir', 'valor_inss', 'valor_tributos'
];

const integerFields = [
  'total_parcelas'
];

const timestampFields = [
  'data_pedido', 'data_emissao', 'data_cad', 'data_mod'
];

function sql(val) {
  if (val === null || val === undefined || val === '') return 'NULL';
  return "'" + String(val).replace(/\$/g, '$ ').replace(/'/g, "''") + "'";
}

function sqlTimestamp(epochSeconds) {
  if (epochSeconds === null || epochSeconds === undefined || epochSeconds === '') return 'NULL';
  const n = Number(epochSeconds);
  if (!Number.isFinite(n)) return 'NULL';
  return `to_timestamp(${Math.trunc(n)})`;
}

return rows.map((row) => {
  const out = { ...row };

  for (const field of textFields) {
    out['_' + field] = sql(row[field]);
  }

  for (const field of numberFields) {
    out['_' + field] = row[field] !== undefined && row[field] !== null && row[field] !== ''
      ? Number(row[field])
      : 'NULL';
  }

  for (const field of integerFields) {
    out['_' + field] = row[field] !== undefined && row[field] !== null && row[field] !== ''
      ? parseInt(row[field], 10)
      : 'NULL';
  }

  for (const field of timestampFields) {
    out['_' + field] = sqlTimestamp(row[field]);
  }

  out._itens_received = ctx.itens_received || rows.length;
  out._itens_processed = ctx.itens_processed || rows.length;

  return out;
});

const prepared = $items('Validar e Organizar Dados', 0, 0)[0].json;
return {
  statusCode: 201,
  body: {
    message: 'Service NF processed successfully',
    itens_received: prepared.itens_received || 0,
    itens_processed: prepared.itens_processed || 0
  }
};

const input = $input.first().json;
const msg = input?.body?.error || input?.message || 'Service NF processing error';
return {
  statusCode: input.statusCode || 500,
  body: { ok: false, error: msg }
};
